const t=s=>[...document.querySelectorAll(s)].map(e=>e.textContent.trim().replace(/\s+/g,' ').slice(0,120));
return {title:document.title,lang:document.documentElement.lang,h1:t('h1'),header:(document.querySelector('header')||{}).innerText,current:t('[aria-current="page"]'),btn:t('header a,header button'),banner:t('[role=status],[role=region],.bandeau,[class*=repli],[class*=banner]'),main:!!document.querySelector('main#contenu,main'),skip:t('a[href^="#"]').slice(0,2),ext:[...document.querySelectorAll('[src],[href]')].map(e=>e.src||e.href).filter(x=>x.startsWith('http')&&!x.startsWith('http://127.0.0.1'))}});
out.push({u,status:r.status(),...d});
}
return out;}

